import json

def norm(path):
    if not path:
        return path
    parts = []
    for p in path.split('/'):
        if p == '' or p == '.':
            continue
        if p == '..':
            if parts:
                parts.pop()
            continue
        parts.append(p)
    return '/' + '/'.join(parts)

def parent(path):
    p = norm(path)
    if p == '/':
        return None
    i = p.rfind('/')
    return '/' if i == 0 else p[:i]

def basename(path):
    p = norm(path)
    if p == '/':
        return '/'
    return p.rsplit('/', 1)[-1]

def gather_files_from_tree(node, cur):
    out = []
    if isinstance(node, dict):
        for name, child in node.items():
            child_path = cur.rstrip('/') + '/' + name if cur != '/' else '/' + name
            if isinstance(child, dict):
                out.extend(gather_files_from_tree(child, child_path))
            else:
                out.append(norm(child_path))
    return out

files = set()

pwc = data.get('pre_write_content')
if isinstance(pwc, dict):
    files.update(gather_files_from_tree(pwc, '/testbed/data'))
elif isinstance(pwc, list):
    for x in pwc:
        if isinstance(x, str):
            files.add(norm(x))
        elif isinstance(x, dict):
            path = x.get('path')
            if isinstance(path, str):
                files.add(norm(path))

for w in data.get('writes', []) or []:
    path = w.get('path')
    if not isinstance(path, str):
        continue
    p = norm(path)
    op = (w.get('op') or w.get('operation') or w.get('type') or '').lower()
    kind = (w.get('kind') or '').lower()
    status = str(w.get('status', '')).lower()
    success = w.get('success')
    failed = (success is False) or ('fail' in status) or ('error' in status)
    if failed:
        continue

    if op in ('delete', 'remove', 'rm', 'unlink'):
        if kind == 'dir' or w.get('recursive'):
            prefix = p.rstrip('/') + '/'
            files = {f for f in files if not (f == p or f.startswith(prefix))}
