import json

def get_read_result(op, path):
    for item in data.get('reads', []):
        if item.get('op') == op and item.get('path') == path:
            return item.get('result')
    return None

def norm(path):
    if path == "":
        return "/"
    parts = []
    abs_path = path.startswith("/")
    for p in path.split("/"):
        if p == "" or p == ".":
            continue
        if p == "..":
            if parts:
                parts.pop()
            continue
        parts.append(p)
    return "/" + "/".join(parts) if abs_path else "/".join(parts)

def parent(path):
    p = norm(path)
    if p == "/":
        return None
    q = p.rsplit("/", 1)[0]
    return q if q else "/"

def basename(path):
    p = norm(path)
    if p == "/":
        return "/"
    return p.rsplit("/", 1)[-1]

def join(a, b):
    if a.endswith("/"):
        return norm(a + b)
    return norm(a + "/" + b)

def parse_listing_entries(obj):
    entries = []
    if obj is None:
        return entries
    if isinstance(obj, dict):
        if isinstance(obj.get("entries"), list):
            for e in obj["entries"]:
                if isinstance(e, dict):
                    entries.append(e)
        elif isinstance(obj.get("children"), list):
            for e in obj["children"]:
                if isinstance(e, dict):
                    entries.append(e)
    elif isinstance(obj, list):
        for e in obj:
            if isinstance(e, dict):
                entries.append(e)
            elif isinstance(e, str):
                entries.append({"name": e})
    return entries

def parse_trace_files(obj):
    files = set()
    dirs = set()
    if obj is None:
        return files, dirs
    def walk(node, cur):
        if isinstance(node, dict):
            t = node.get("type")
            if t == "file":
                files.add(cur)
                return
            if t == "dir":
                dirs.add(cur)
                children = node.get("children")
                if isinstance(children, dict):
                    for name, child in children.items():
                        walk(child, join(cur, name))
                elif isinstance(children, list):
                    for child in children:
                        if isinstance(child, dict):
                            name = child.get("name")
                            if isinstance(name, str):
                                walk(child, join(cur, name))
                return
            if "path" in node and "type" in node:
                p = norm(node["path"])
                if node["type"] == "file":
                    files.add(p)
                elif node["type"] == "dir":
                    dirs.add(p)
            for v in node.values():
                if isinstance(v, (dict, list)):
                    walk(v, cur)
        elif isinstance(node, list):
            for item in node:
                walk(item, cur)
    walk(obj, "/testbed/data")
    return files, dirs

base_list = get_read_result("list", "/testbed/data")
base_trace = get_read_result("trace", "/testbed/data")

existing_files, existing_dirs = parse_trace_files(base_trace)
existing_dirs.add("/testbed/data")

for e in parse_listing_entries(base_list):
    name = e.get("name")
    if not isinstance(name, str):
        continue
    p = join("/testbed/data", name)
    t = e.get("type")
    if t == "file":
        existing_files.add(p)
    elif t == "dir":
        existing_dirs.add(p)

writes = data.get("writes", [])

for w in writes:
    if not isinstance(w, dict):
        continue
    path = w.get("path") or w.get("target") or w.get("file") or w.get("filepath")
    if not isinstance(path, str):
        continue
    p = norm(path)
    if not p.startswith("/testbed/data"):
        continue
    status = str(w.get("status", "")).lower()
    ok = w.get("ok")
    success = (ok is True) or ("success" in status and "fail" not in status and "error" not in status)
    if not success:
        continue
    kind = str(w.get("kind", "")).lower()
    op = str(w.get("op", "")).lower()
    action = str(w.get("action", "")).lower()
    text = ""
    if kind in ("delete", "remove", "unlink") or op in ("delete", "remove", "unlink") or action in ("delete", "remove", "unlink"):
        if p in existing_files:
            existing_files.discard(p)
        continue
    existing_files.add(p)
    cur = parent(p)
    while cur and cur.startswith("/testbed/data"):
        existing_dirs.add(cur)
        if cur == "/testbed/data":
            break
        cur = parent(cur)

files = sorted([p for p in existing_files if p.startswith("/testbed/data/")])

out = "\n".join(files[:50])
if files[:50]:
    out += "\n"

print_json({"text": out})

