def apply_write(fs, w):
    path = w.get("path")
    if not isinstance(path, str):
        return
    if w.get("success") is False:
        return
    if "content" in w:
        fs[path] = w.get("content", "")
    elif w.get("op") == "delete":
        fs.pop(path, None)

